# Pulumi ComponentResource: Service Infrastructure

Here's a complete Pulumi TypeScript implementation with a `ComponentResource` wrapping S3, RDS, and IAM resources.

## Project Structure

```
├── Pulumi.yaml
├── Pulumi.dev.yaml
├── Pulumi.prod.yaml
├── package.json
├── tsconfig.json
├── index.ts
└── components/
    └── service-infra.ts
```

## Configuration Files

### `Pulumi.yaml`
```yaml
name: service-infra
runtime: nodejs
description: Service infrastructure with S3, RDS, and IAM
```

### `Pulumi.dev.yaml`
```yaml
config:
  aws:region: us-east-1
  service-infra:environment: dev
  service-infra:dbInstanceClass: db.t3.micro
  service-infra:dbMultiAz: false
  service-infra:dbAllocatedStorage: 20
  service-infra:dbBackupRetention: 7
  service-infra:dbMasterUsername: dbadmin
  service-infra:dbMasterPassword:
    secure: AAABAJ... # pulumi config set --secret dbMasterPassword
  service-infra:enableReplication: false
```

### `Pulumi.prod.yaml`
```yaml
config:
  aws:region: us-east-1
  service-infra:environment: prod
  service-infra:dbInstanceClass: db.t3.medium
  service-infra:dbMultiAz: true
  service-infra:dbAllocatedStorage: 100
  service-infra:dbBackupRetention: 30
  service-infra:dbMasterUsername: dbadmin
  service-infra:dbMasterPassword:
    secure: AAABAJ... # pulumi config set --secret dbMasterPassword
  service-infra:enableReplication: true
  service-infra:replicationRegion: us-west-2
```

## Component Implementation

### `components/service-infra.ts`

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

export interface ServiceInfraArgs {
    environment: string;
    dbInstanceClass: string;
    dbMultiAz: boolean;
    dbAllocatedStorage: number;
    dbBackupRetention: number;
    dbMasterUsername: string;
    dbMasterPassword: pulumi.Input<string>;
    enableReplication: boolean;
    replicationRegion?: string;
    tags?: { [key: string]: string };
}

export class ServiceInfra extends pulumi.ComponentResource {
    public readonly bucket: aws.s3.BucketV2;
    public readonly bucketEncryption: aws.s3.BucketServerSideEncryptionConfigurationV2;
    public readonly bucketVersioning: aws.s3.BucketVersioningV2;
    public readonly bucketPublicAccessBlock: aws.s3.BucketPublicAccessBlock;
    public readonly replicationBucket?: aws.s3.BucketV2;
    public readonly replicationRole?: aws.iam.Role;
    public readonly dbSubnetGroup: aws.rds.SubnetGroup;
    public readonly dbSecurityGroup: aws.ec2.SecurityGroup;
    public readonly dbInstance: aws.rds.Instance;
    public readonly serviceRole: aws.iam.Role;
    public readonly servicePolicy: aws.iam.Policy;
    public readonly connectionStringSecret: aws.secretsmanager.Secret;
    public readonly connectionStringSecretVersion: aws.secretsmanager.SecretVersion;

    constructor(name: string, args: ServiceInfraArgs, opts?: pulumi.ComponentResourceOptions) {
        super("custom:components:ServiceInfra", name, {}, opts);

        const defaultTags = {
            Environment: args.environment,
            ManagedBy: "pulumi",
            Component: name,
            ...args.tags,
        };

        // =========================================================================
        // S3 Bucket with Versioning and Encryption
        // =========================================================================
        this.bucket = new aws.s3.BucketV2(`${name}-assets`, {
            bucket: `${name}-assets-${args.environment}`,
            tags: defaultTags,
        }, { parent: this });

        this.bucketVersioning = new aws.s3.BucketVersioningV2(`${name}-versioning`, {
            bucket: this.bucket.id,
            versioningConfiguration: {
                status: "Enabled",
            },
        }, { parent: this });

        this.bucketEncryption = new aws.s3.BucketServerSideEncryptionConfigurationV2(`${name}-encryption`, {
            bucket: this.bucket.id,
            rules: [{
                applyServerSideEncryptionByDefault: {
                    sseAlgorithm: "AES256",
                },
                bucketKeyEnabled: true,
            }],
        }, { parent: this });

        this.bucketPublicAccessBlock = new aws.s3.BucketPublicAccessBlock(`${name}-pab`, {
            bucket: this.bucket.id,
            blockPublicAcls: true,
            blockPublicPolicy: true,
            ignorePublicAcls: true,
            restrictPublicBuckets: true,
        }, { parent: this });

        // Cross-region replication for prod
        if (args.enableReplication && args.replicationRegion) {
            const replicationProvider = new aws.Provider(`${name}-replication-provider`, {
                region: args.replicationRegion,
            }, { parent: this });

            this.replicationBucket = new aws.s3.BucketV2(`${name}-assets-replica`, {
                bucket: `${name}-assets-${args.environment}-replica`,
                tags: defaultTags,
            }, { parent: this, provider: replicationProvider });

            new aws.s3.BucketVersioningV2(`${name}-replica-versioning`, {
                bucket: this.replicationBucket.id,
                versioningConfiguration: {
                    status: "Enabled",
                },
            }, { parent: this, provider: replicationProvider });

            new aws.s3.BucketServerSideEncryptionConfigurationV2(`${name}-replica-encryption`, {
                bucket: this.replicationBucket.id,
                rules: [{
                    applyServerSideEncryptionByDefault: {
                        sseAlgorithm: "AES256",
                    },
                }],
            }, { parent: this, provider: replicationProvider });

            // IAM role for replication
            this.replicationRole = new aws.iam.Role(`${name}-replication-role`, {
                assumeRolePolicy: JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [{
                        Effect: "Allow",
                        Principal: { Service: "s3.amazonaws.com" },
                        Action: "sts:AssumeRole",
                    }],
                }),
                tags: defaultTags,
            }, { parent: this });

            new aws.iam.RolePolicy(`${name}-replication-policy`, {
                role: this.replicationRole.id,
                policy: pulumi.all([this.bucket.arn, this.replicationBucket.arn]).apply(([sourceArn, destArn]) =>
                    JSON.stringify({
                        Version: "2012-10-17",
                        Statement: [
                            {
                                Effect: "Allow",
                                Action: ["s3:GetReplicationConfiguration", "s3:ListBucket"],
                                Resource: sourceArn,
                            },
                            {
                                Effect: "Allow",
                                Action: ["s3:GetObjectVersionForReplication", "s3:GetObjectVersionAcl"],
                                Resource: `${sourceArn}/*`,
                            },
                            {
                                Effect: "Allow",
                                Action: ["s3:ReplicateObject", "s3:ReplicateDelete"],
                                Resource: `${destArn}/*`,
                            },
                        ],
                    })
                ),
            }, { parent: this });

            new aws.s3.BucketReplicationConfiguration(`${name}-replication`, {
                bucket: this.bucket.id,
                role: this.replicationRole.arn,
                rules: [{
                    id: "replicate-all",
                    status: "Enabled",
                    destination: {
                        bucket: this.replicationBucket.arn,
                        storageClass: "STANDARD_IA",
                    },
                }],
            }, { parent: this, dependsOn: [this.bucketVersioning] });
        }

        // =========================================================================
        // RDS PostgreSQL with Deletion Protection
        // =========================================================================
        const vpc = aws.ec2.getVpcOutput({ default: true });

        this.dbSubnetGroup = new aws.rds.SubnetGroup(`${name}-db-subnet`, {
            subnetIds: vpc.apply(v => 
                aws.ec2.getSubnets({
                    filters: [{ name: "vpc-id", values: [v.id] }],
                }).then(subnets => subnets.ids)
            ),
            tags: defaultTags,
        }, { parent: this });

        this.dbSecurityGroup = new aws.ec2.SecurityGroup(`${name}-db-sg`, {
            vpcId: vpc.id,
            description: "Security group for RDS PostgreSQL",
            ingress: [{
                protocol: "tcp",
                fromPort: 5432,
                toPort: 5432,
                cidrBlocks: ["10.0.0.0/8"], // Internal only
                description: "PostgreSQL from internal",
            }],
            egress: [{
                protocol: "-1",
                fromPort: 0,
                toPort: 0,
                cidrBlocks: ["0.0.0.0/0"],
            }],
            tags: defaultTags,
        }, { parent: this });

        this.dbInstance = new aws.rds.Instance(`${name}-db`, {
            identifier: `${name}-db-${args.environment}`,
            engine: "postgres",
            engineVersion: "15.4",
            instanceClass: args.dbInstanceClass,
            allocatedStorage: args.dbAllocatedStorage,
            storageType: "gp3",
            storageEncrypted: true,
            multiAz: args.dbMultiAz,
            dbName: "appdb",
            username: args.dbMasterUsername,
            password: args.dbMasterPassword,
            dbSubnetGroupName: this.dbSubnetGroup.name,
            vpcSecurityGroupIds: [this.dbSecurityGroup.id],
            backupRetentionPeriod: args.dbBackupRetention,
            backupWindow: "03:00-04:00",
            maintenanceWindow: "Mon:04:00-Mon:05:00",
            deletionProtection: true,
            skipFinalSnapshot: args.environment === "dev",
            finalSnapshotIdentifier: args.environment === "prod" 
                ? `${name}-db-final-snapshot` 
                : undefined,
            publiclyAccessible: false,
            autoMinorVersionUpgrade: true,
            performanceInsightsEnabled: args.environment === "prod",
            tags: defaultTags,
        }, { parent: this });

        // =========================================================================
        // IAM Role for Service Accounts (IRSA-compatible)
        // =========================================================================
        const assumeRolePolicy = args.environment === "prod"
            ? JSON.stringify({
                Version: "2012-10-17",
                Statement: [{
                    Effect: "Allow",
                    Principal: { Service: "ec2.amazonaws.com" },
                    Action: "sts:AssumeRole",
                }],
            })
            : JSON.stringify({
                Version: "2012-10-17",
                Statement: [{
                    Effect: "Allow",
                    Principal: { Service: "ec2.amazonaws.com" },
                    Action: "sts:AssumeRole",
                }],
            });

        this.serviceRole = new aws.iam.Role(`${name}-service-role`, {
            name: `${name}-service-${args.environment}`,
            assumeRolePolicy,
            tags: defaultTags,
        }, { parent: this });

        // Least-privilege policy - no wildcards in prod
        const bucketPolicy = args.environment === "prod"
            ? pulumi.all([this.bucket.arn]).apply(([bucketArn]) =>
                JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [
                        {
                            Sid: "ListBucket",
                            Effect: "Allow",
                            Action: ["s3:ListBucket"],
                            Resource: bucketArn,
                        },
                        {
                            Sid: "ObjectOperations",
                            Effect: "Allow",
                            Action: [
                                "s3:GetObject",
                                "s3:PutObject",
                                "s3:DeleteObject",
                            ],
                            Resource: `${bucketArn}/*`,
                        },
                        {
                            Sid: "SecretsAccess",
                            Effect: "Allow",
                            Action: ["secretsmanager:GetSecretValue"],
                            Resource: `arn:aws:secretsmanager:*:*:secret:${name}-*`,
                        },
                    ],
                })
            )
            : pulumi.all([this.bucket.arn]).apply(([bucketArn]) =>
                JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [
                        {
                            Sid: "BucketAccess",
                            Effect: "Allow",
                            Action: ["s3:*"],
                            Resource: [bucketArn, `${bucketArn}/*`],
                        },
                    ],
                })
            );

        this.servicePolicy = new aws.iam.Policy(`${name}-service-policy`, {
            name: `${name}-service-policy-${args.environment}`,
            policy: bucketPolicy,
            tags: defaultTags,
        }, { parent: this });

        new aws.iam.RolePolicyAttachment(`${name}-policy-attachment`, {
            role: this.serviceRole.name,
            policyArn: this.servicePolicy.arn,
        }, { parent: this });

        // =========================================================================
        // Secrets Manager for DB Connection String
        // =========================================================================
        this.connectionStringSecret = new aws.secretsmanager.Secret(`${name}-db-connection`, {
            name: `${name}-db-connection-${args.environment}`,
            description: "Database connection string",
            tags: defaultTags,
        }, { parent: this });

        this.connectionStringSecretVersion = new aws.secretsmanager.SecretVersion(`${name}-db-connection-version`, {
            secretId: this.connectionStringSecret.id,
            secretString: pulumi.all([
                this.dbInstance.endpoint,
                args.dbMasterUsername,
                args.dbMasterPassword,
            ]).apply(([endpoint, username, password]) =>
                `postgresql://${username}:${password}@${endpoint}/appdb`
            ),
        }, { parent: this });

        this.registerOutputs({
            bucketArn: this.bucket.arn,
            bucketName: this.bucket.bucket,
            dbEndpoint: this.dbInstance.endpoint,
            dbArn: this.dbInstance.arn,
            serviceRoleArn: this.serviceRole.arn,
            connectionStringSecretArn: this.connectionStringSecret.arn,
        });
    }
}
```

## Main Entry Point

### `index.ts`

```typescript
import * as pulumi from "@pulumi/pulumi";
import { ServiceInfra } from "./components/service-infra";

const config = new pulumi.Config();

const environment = config.require("environment");
const dbInstanceClass = config.require("dbInstanceClass");
const dbMultiAz = config.requireBoolean("dbMultiAz");
const dbAllocatedStorage = config.requireNumber("dbAllocatedStorage");
const dbBackupRetention = config.requireNumber("dbBackupRetention");
const dbMasterUsername = config.require("dbMasterUsername");
const dbMasterPassword = config.requireSecret("dbMasterPassword");
const enableReplication = config.getBoolean("enableReplication") ?? false;
const replicationRegion = config.get("replicationRegion");

const infra = new ServiceInfra("app", {
    environment,
    dbInstanceClass,
    dbMultiAz,
    dbAllocatedStorage,
    dbBackupRetention,
    dbMasterUsername,
    dbMasterPassword,
    enableReplication,
    replicationRegion,
    tags: {
        Project: "myapp",
        Team: "platform",
    },
});

export const bucketName = infra.bucket.bucket;
export const bucketArn = infra.bucket.arn;
export const dbEndpoint = infra.dbInstance.endpoint;
export const serviceRoleArn = infra.serviceRole.arn;
export const connectionStringSecretArn = infra.connectionStringSecret.arn;
```

